class ValidationException(Exception):
    def __init__(
        self,
        errors: Sequence[Any],
        *,
        endpoint_ctx: Optional[Dict[str, Any]] = None,
    ) -> None:
        self._errors = errors
        self.endpoint_ctx = endpoint_ctx or {}

    def errors(self) -> Sequence[Any]:
        return self._errors

    def __str__(self) -> str:
        message = f"{len(self._errors)} validation errors:\n"
        for err in self._errors:
            message += f"  {err}\n"
        ctx = self.endpoint_ctx
        if ctx:
            method = ctx.get("method")
            path = ctx.get("path")
            route = f"{method} {path}" if method and path else (path or "")
            message += (
                f'  File "{ctx.get("file")}", line {ctx.get("line")}, '
                f"in {ctx.get('function')}\n"
            )
            if route:
                message += f"    {route}\n"
        return message


